CREATE TYPE "LocaleDirection" AS ENUM ('LTR','RTL');
CREATE TYPE "CmsFieldType" AS ENUM ('TEXT','TEXTAREA','RICH_TEXT','MARKDOWN','INTEGER','DECIMAL','BOOLEAN','DATE','DATETIME','SELECT','MULTISELECT','EMAIL','URL','JSON');
CREATE TYPE "CmsContentStatus" AS ENUM ('DRAFT','IN_REVIEW','SCHEDULED','PUBLISHED','ARCHIVED');
CREATE TABLE "locales" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"nativeName" TEXT NOT NULL,"direction" "LocaleDirection" NOT NULL DEFAULT 'LTR',"isDefault" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"fallbackLocaleId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "locales_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "locales_code_key" ON "locales"("code");
CREATE INDEX "locales_isActive_isDefault_idx" ON "locales"("isActive","isDefault");
CREATE INDEX "locales_fallbackLocaleId_idx" ON "locales"("fallbackLocaleId");
CREATE TABLE "content_types" ("id" UUID NOT NULL,"key" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "content_types_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "content_types_key_key" ON "content_types"("key");
CREATE INDEX "content_types_isActive_createdAt_idx" ON "content_types"("isActive","createdAt");
CREATE TABLE "content_type_fields" ("id" UUID NOT NULL,"contentTypeId" UUID NOT NULL,"key" TEXT NOT NULL,"label" TEXT NOT NULL,"type" "CmsFieldType" NOT NULL,"isRequired" BOOLEAN NOT NULL DEFAULT false,"isLocalized" BOOLEAN NOT NULL DEFAULT true,"isActive" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"config" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "content_type_fields_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "content_type_fields_contentTypeId_key_key" ON "content_type_fields"("contentTypeId","key");
CREATE INDEX "content_type_fields_contentTypeId_isActive_sortOrder_idx" ON "content_type_fields"("contentTypeId","isActive","sortOrder");
CREATE TABLE "cms_contents" ("id" UUID NOT NULL,"contentTypeId" UUID NOT NULL,"createdById" UUID,"data" JSONB NOT NULL DEFAULT '{}'::jsonb,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "cms_contents_pkey" PRIMARY KEY ("id"));
CREATE INDEX "cms_contents_contentTypeId_createdAt_idx" ON "cms_contents"("contentTypeId","createdAt");
CREATE INDEX "cms_contents_createdById_idx" ON "cms_contents"("createdById");
CREATE TABLE "cms_content_translations" ("id" UUID NOT NULL,"contentId" UUID NOT NULL,"localeId" UUID NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"excerpt" TEXT,"data" JSONB NOT NULL DEFAULT '{}'::jsonb,"seoTitle" TEXT,"seoDescription" TEXT,"status" "CmsContentStatus" NOT NULL DEFAULT 'DRAFT',"version" INTEGER NOT NULL DEFAULT 1,"publishedAt" TIMESTAMP(3),"scheduledAt" TIMESTAMP(3),"publishedSlug" TEXT,"publishedSnapshot" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "cms_content_translations_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "cms_content_translations_contentId_localeId_key" ON "cms_content_translations"("contentId","localeId");
CREATE UNIQUE INDEX "cms_content_translations_localeId_slug_key" ON "cms_content_translations"("localeId","slug");
CREATE UNIQUE INDEX "cms_content_translations_localeId_publishedSlug_key" ON "cms_content_translations"("localeId","publishedSlug");
CREATE INDEX "cms_content_translations_localeId_status_updatedAt_idx" ON "cms_content_translations"("localeId","status","updatedAt");
CREATE INDEX "cms_content_translations_status_scheduledAt_idx" ON "cms_content_translations"("status","scheduledAt");
CREATE INDEX "cms_content_translations_publishedAt_idx" ON "cms_content_translations"("publishedAt");
CREATE TABLE "cms_content_revisions" ("id" UUID NOT NULL,"translationId" UUID NOT NULL,"version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"changeNote" TEXT,"createdById" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "cms_content_revisions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "cms_content_revisions_translationId_version_key" ON "cms_content_revisions"("translationId","version");
CREATE INDEX "cms_content_revisions_translationId_createdAt_idx" ON "cms_content_revisions"("translationId","createdAt");
ALTER TABLE "locales" ADD CONSTRAINT "locales_fallbackLocaleId_fkey" FOREIGN KEY ("fallbackLocaleId") REFERENCES "locales"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "content_type_fields" ADD CONSTRAINT "content_type_fields_contentTypeId_fkey" FOREIGN KEY ("contentTypeId") REFERENCES "content_types"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "cms_contents" ADD CONSTRAINT "cms_contents_contentTypeId_fkey" FOREIGN KEY ("contentTypeId") REFERENCES "content_types"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "cms_contents" ADD CONSTRAINT "cms_contents_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "cms_content_translations" ADD CONSTRAINT "cms_content_translations_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "cms_contents"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "cms_content_translations" ADD CONSTRAINT "cms_content_translations_localeId_fkey" FOREIGN KEY ("localeId") REFERENCES "locales"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "cms_content_revisions" ADD CONSTRAINT "cms_content_revisions_translationId_fkey" FOREIGN KEY ("translationId") REFERENCES "cms_content_translations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "cms_content_revisions" ADD CONSTRAINT "cms_content_revisions_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
